import sys
import numpy as np

def excute_min_m(a):
    m = len(a)
    for i,a_i in enumerate(a[:-1]):
        for j,a_j in enumerate(a[i+1:]):
            if a_i == a_j:
                m = min(j+i+2, m)
    print(m)

def solve(s: int):
    a = []
    a.append(s)
    tmp = s
    flag = False
    b = [4, 2, 1, 4]
    while not flag:
        if tmp%2==0:
            tmp = tmp//2
        else:
            tmp = 3*tmp + 1
        a.append(tmp)
        if len(a) >= 4 and a[-4:] == b:
            flag = True
    excute_min_m(a)
    return


# Generated by 1.1.6 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    s = int(next(tokens))  # type: int
    solve(s)

if __name__ == '__main__':
    main()
